CREATE ROLE budget_lpc_app NOLOGIN NOSUPERUSER NOCREATEDB NOCREATEROLE NOINHERIT;
CREATE SCHEMA budget_lpc;
REVOKE ALL ON SCHEMA budget_lpc FROM PUBLIC, anon, authenticated;
SET search_path TO budget_lpc, pg_catalog;
CREATE TABLE IF NOT EXISTS accounts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, bank TEXT NOT NULL DEFAULT '', currency TEXT NOT NULL, profile TEXT NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS categories(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, name TEXT NOT NULL UNIQUE, parent_id INTEGER REFERENCES categories(id), color TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS batches(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, account_id INTEGER NOT NULL REFERENCES accounts(id), filename TEXT NOT NULL, file_hash TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text), imported INTEGER NOT NULL, duplicates INTEGER NOT NULL, start TEXT, "end" TEXT, coverage_confirmed INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS transactions(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, date TEXT NOT NULL, description TEXT NOT NULL, cents INTEGER NOT NULL, currency TEXT NOT NULL, kind TEXT NOT NULL, status TEXT NOT NULL, category_id INTEGER REFERENCES categories(id), account_id INTEGER REFERENCES accounts(id), label TEXT NOT NULL DEFAULT '', expense_type TEXT NOT NULL DEFAULT 'variable', source TEXT NOT NULL, source_key TEXT UNIQUE, batch_id INTEGER REFERENCES batches(id), notes TEXT NOT NULL DEFAULT '', suggestion TEXT, matched_to_id INTEGER REFERENCES transactions(id), created_at TEXT NOT NULL DEFAULT (CURRENT_TIMESTAMP::text));
CREATE INDEX IF NOT EXISTS transaction_period ON transactions(currency,date,status);
CREATE TABLE IF NOT EXISTS bank_keys(account_id INTEGER NOT NULL REFERENCES accounts(id), fingerprint TEXT NOT NULL, transaction_id INTEGER NOT NULL REFERENCES transactions(id), PRIMARY KEY(account_id,fingerprint));
CREATE TABLE IF NOT EXISTS budgets(month TEXT NOT NULL,currency TEXT NOT NULL,income_cents INTEGER NOT NULL DEFAULT 0,investment_cents INTEGER NOT NULL DEFAULT 0,limits TEXT NOT NULL DEFAULT '{}',PRIMARY KEY(month,currency));
CREATE TABLE IF NOT EXISTS meta(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS owner_sessions(digest TEXT PRIMARY KEY,expires INTEGER NOT NULL,credential_version TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS login_failures(client TEXT NOT NULL,at INTEGER NOT NULL);
ALTER TABLE transactions ADD COLUMN match_original_account_id INTEGER;
ALTER TABLE accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY budget_owner_access ON accounts TO budget_lpc_app USING (true) WITH CHECK (true);
ALTER TABLE categories ENABLE ROW LEVEL SECURITY;
CREATE POLICY budget_owner_access ON categories TO budget_lpc_app USING (true) WITH CHECK (true);
ALTER TABLE batches ENABLE ROW LEVEL SECURITY;
CREATE POLICY budget_owner_access ON batches TO budget_lpc_app USING (true) WITH CHECK (true);
ALTER TABLE transactions ENABLE ROW LEVEL SECURITY;
CREATE POLICY budget_owner_access ON transactions TO budget_lpc_app USING (true) WITH CHECK (true);
ALTER TABLE bank_keys ENABLE ROW LEVEL SECURITY;
CREATE POLICY budget_owner_access ON bank_keys TO budget_lpc_app USING (true) WITH CHECK (true);
ALTER TABLE budgets ENABLE ROW LEVEL SECURITY;
CREATE POLICY budget_owner_access ON budgets TO budget_lpc_app USING (true) WITH CHECK (true);
ALTER TABLE meta ENABLE ROW LEVEL SECURITY;
CREATE POLICY budget_owner_access ON meta TO budget_lpc_app USING (true) WITH CHECK (true);
ALTER TABLE owner_sessions ENABLE ROW LEVEL SECURITY;
CREATE POLICY budget_owner_access ON owner_sessions TO budget_lpc_app USING (true) WITH CHECK (true);
ALTER TABLE login_failures ENABLE ROW LEVEL SECURITY;
CREATE POLICY budget_owner_access ON login_failures TO budget_lpc_app USING (true) WITH CHECK (true);
GRANT USAGE ON SCHEMA budget_lpc TO budget_lpc_app;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA budget_lpc TO budget_lpc_app;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA budget_lpc TO budget_lpc_app;
RESET search_path;

